glm::vec3 rij = pj->pos - pi->pos;
float r = glm::length(rij);
if (r >= h || r == 0.0f) return;

glm::vec3 dir = (r != 0.0f) ? rij / r : glm::vec3(0.0f);

float q = r / h;
float q2 = q * q;
float q3 = q2 * q;

float W_pressure = spikyGrad * (h - r) * (h - r);
glm::vec3 f_pressure = -mass * (pi->pressure / (pi->density * pi->density) + pj->pressure / (pj->density * pj->density)) * W_pressure * dir;

float W_viscosity = spikyLap * (h - r);
glm::vec3 f_viscosity = viscosity * mass * (pj->velocity - pi->velocity) / pj->density * W_viscosity;

force += f_pressure + f_viscosity;
// END_CODE

